    private static string Route(string id)=>"/api/credit-orders/commands/"+id;
    private static CreditOrderInput Input(JsonNode quote)=>new(V(quote,"id"),V(quote,"fingerprint"),"Synthetic cheque QA","09100000000",new("IR","تهران","تهران","نشانی کاملاً ساختگی سفارش چکی در QA","1234567890"),"Software QA only; no real purchase or person",true,true);
    private async Task<Goods> Product(int stock=5)
    {
        var plan=await Plan();await using var scope=sql.Factory.Services.CreateAsyncScope();var sp=scope.ServiceProvider;var catalog=sp.GetRequiredService<CatalogDbContext>();var payments=sp.GetRequiredService<PaymentsDbContext>();var method=new PurchaseMethod{NameFa="چک ساختگی سفارش",NameEn="Synthetic order cheque",Kind="cheque",Enabled=true,RequiresApproval=true};payments.Methods.Add(method);await payments.SaveChangesAsync();
        var category=await catalog.Categories.Where(x=>x.IsActive).Select(x=>x.Id).FirstAsync();var brand=await catalog.Brands.Where(x=>x.IsActive).Select(x=>x.Id).FirstAsync();var product=new Product{Slug="creditorder-"+Id(),CategoryId=category,BrandId=brand,Status="Published",Translations=[new(){Locale="fa",Name="کالای ساختگی سفارش چکی",SearchName="ساختگی"},new(){Locale="en",Name="Synthetic cheque order item",SearchName="synthetic"}],PurchaseMethods=[new(){MethodId=method.Id}],CreditPlans=[new(){PlanId=plan.Id}]};var variant=new ProductVariant{Sku="CREDITORDER-"+Id(),SearchSku="qa",PriceRial=100003,IsActive=true};product.Variants.Add(variant);catalog.Products.Add(product);await catalog.SaveChangesAsync();var inventory=sp.GetRequiredService<InventoryDbContext>();inventory.Stock.Add(new(){VariantId=variant.Id,OnHand=stock});await inventory.SaveChangesAsync();
        var sales=sp.GetRequiredService<SalesDbContext>();Assert.StartsWith("SaymanTest_",sales.Database.GetDbConnection().Database);await using(var tx=await sales.Database.BeginTransactionAsync(IsolationLevel.Serializable)){var old=await sales.ChargePolicies.AsNoTracking().SingleOrDefaultAsync();await sp.GetRequiredService<CheckoutChargePolicyService>().SaveAsync(new("flat","ارسال ساختگی","Synthetic QA shipping","D21 QA only","D21 QA only","12345",null,"exempt",null,"goods","half_up",old is null?null:Convert.ToBase64String(old.Version)),default);var settings=await sales.OrderSettings.AsNoTracking().SingleOrDefaultAsync();await sp.GetRequiredService<CheckoutOrderSettingsService>().SaveAsync(new(true,60,2,settings is null?null:Convert.ToBase64String(settings.Version),true),default);await tx.CommitAsync();}return new(variant.Id,method.Id,plan);
    }
    internal async Task<ReadyData> Ready(HttpClient finance,HttpClient reviewer,Goods? shared=null,int quantity=1)
    {
        var goods=shared??await Product();var owner=await Customer();var scope=await CreditCheckoutQuoteQa.Scope(owner.Client,finance,reviewer,goods.Plan.Id,goods.Plan.Version);var cart=await Read(await owner.Client.PutAsJsonAsync("/api/cart/en",new CartInput([new(goods.Variant,quantity)],null)));var quote=(await Read(await owner.Client.PostAsJsonAsync(CreditCheckoutQuoteQa.Route(Id()),CreditCheckoutQuoteQa.Input(scope,V(cart,"version"),goods.Method,goods.Plan.Id))))["quote"]!;return new(goods,owner.Client,owner.Owner,scope,quote);
    }
    [Fact]public async Task OrdinaryOrderClaimsOnceHasExactBoundedLegacyHoldAndCancellationNeverRestoresTheScope()
    {
        using var finance=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var s=await Ready(finance,reviewer);using var customer=s.Customer;var command=Id();var path=Route(command);var first=await Read(await customer.PostAsJsonAsync(path,Input(s.Quote)));var order=first["order"]!;var id=V(order["summary"]!,"id");Assert.Equal("AwaitingPayment",V(order["summary"]!,"state"));Assert.Equal(1,order["originalSnapshotVersion"]!.GetValue<int>());Assert.False(order["canPay"]!.GetValue<bool>());Assert.Equal("credit_settlement_pending",V(order,"paymentAvailability"));Assert.True(DateTimeOffset.Parse(V(order["summary"]!,"expiresAt"))<=DateTimeOffset.Parse(V(s.Quote,"expiresAt")));
        var appPath="/api/credit/applications/"+V(s.Scope["application"]!,"id");var used=await Read(await customer.GetAsync(appPath+"/purchase-scope"));Assert.Equal("Used",V(used["scope"]!,"state"));Assert.Equal(id,V(used["scope"]!["use"]!,"orderId"));Assert.False(used["canRevoke"]!.GetValue<bool>());Assert.False(used["eligibleForQuote"]!.GetValue<bool>());
        var receipt=await Read(await customer.GetAsync(path));Assert.True(receipt["replayed"]!.GetValue<bool>());Assert.Equal(order.ToJsonString(),receipt["order"]!.ToJsonString());using(var duplicate=await customer.PostAsJsonAsync(Route(Id()),Input(s.Quote)))Assert.Equal(HttpStatusCode.Conflict,duplicate.StatusCode);
        using(var other=await finance.GetAsync("/api/credit-orders/"+id))Assert.Equal(HttpStatusCode.NotFound,other.StatusCode);
        var cancelled=await Read(await customer.PostAsJsonAsync("/api/orders/v2/"+id+"/cancel",new{version=V(order["summary"]!,"version")}));Assert.Equal("Cancelled",V(cancelled["summary"]!,"state"));Assert.Equal("credit_settlement_pending",V(cancelled,"paymentAvailability"));var current=await Read(await customer.GetAsync("/api/credit-orders/"+id));Assert.Equal("Cancelled",V(current["order"]!["summary"]!,"state"));var replay=await Read(await customer.PostAsJsonAsync(path,Input(s.Quote)));Assert.True(replay["replayed"]!.GetValue<bool>());Assert.Equal(order.ToJsonString(),replay["order"]!.ToJsonString());
        using(var revoke=await customer.PostAsJsonAsync(appPath+"/purchase-scope/revoke/"+Id(),new RevokeCreditPurchaseScopeInput(V(used["application"]!,"version"),V(used["scope"]!,"version"),"fa","ساختگی",true)))Assert.Equal(HttpStatusCode.Conflict,revoke.StatusCode);
        await using var dbScope=sql.Factory.Services.CreateAsyncScope();var sales=dbScope.ServiceProvider.GetRequiredService<SalesDbContext>();var credit=dbScope.ServiceProvider.GetRequiredService<CreditDbContext>();var inventory=dbScope.ServiceProvider.GetRequiredService<InventoryDbContext>();Assert.Single(await sales.CreditOrderLinks.Where(x=>x.OrderId==id).ToArrayAsync());Assert.Single(await credit.PurchaseScopeUses.Where(x=>x.OrderId==id).ToArrayAsync());var hold=await inventory.Reservations.SingleAsync(x=>x.OrderId==id);Assert.Null(hold.ContractVersion);Assert.Equal(DateTimeOffset.Parse(V(order["summary"]!,"expiresAt")),hold.ExpiresAt);Assert.Equal("Released",hold.State.ToString());var stock=await inventory.Stock.SingleAsync(x=>x.VariantId==s.Goods.Variant);Assert.Equal(5,stock.OnHand);Assert.Equal(0,stock.Reserved);Assert.Single(await dbScope.ServiceProvider.GetRequiredService<IdentityContext>().Audit.Where(x=>x.Action=="SALES_CREDIT_ORDER"&&x.Resource==path).ToArrayAsync());
    }
    [Fact]public async Task AuditFailureRollsBackScopeOrderStockAndCartAndRetryWithSameCommandCanCommitOnce()
    {
        using var finance=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var s=await Ready(finance,reviewer);using var customer=s.Customer;var command=Id();var path=Route(command);
        await using(var scope=sql.Factory.Services.CreateAsyncScope())await scope.ServiceProvider.GetRequiredService<IdentityContext>().Database.ExecuteSqlRawAsync("ALTER TABLE [identity].[Audit] WITH NOCHECK ADD CONSTRAINT CK_QA_CreditOrderAudit CHECK ([Action]<>'SALES_CREDIT_ORDER')");
        try{using var failed=await customer.PostAsJsonAsync(path,Input(s.Quote));Assert.Equal(HttpStatusCode.Conflict,failed.StatusCode);}finally{await using var scope=sql.Factory.Services.CreateAsyncScope();await scope.ServiceProvider.GetRequiredService<IdentityContext>().Database.ExecuteSqlRawAsync("ALTER TABLE [identity].[Audit] DROP CONSTRAINT CK_QA_CreditOrderAudit");}
        await using(var scope=sql.Factory.Services.CreateAsyncScope()){var sales=scope.ServiceProvider.GetRequiredService<SalesDbContext>();Assert.False(await sales.Orders.AnyAsync(x=>x.OwnerId==s.Owner));Assert.False(await scope.ServiceProvider.GetRequiredService<CreditDbContext>().PurchaseScopeUses.AnyAsync(x=>x.ScopeId==V(s.Scope["scope"]!,"id")));Assert.Equal(0,(await scope.ServiceProvider.GetRequiredService<InventoryDbContext>().Stock.SingleAsync(x=>x.VariantId==s.Goods.Variant)).Reserved);Assert.Single(await sales.CartLines.Where(x=>x.VariantId==s.Goods.Variant).ToArrayAsync());}
        var replies=await Task.WhenAll((await Task.WhenAll(customer.PostAsJsonAsync(path,Input(s.Quote)),customer.PostAsJsonAsync(path,Input(s.Quote)))).Select(Read));Assert.Single(replies,x=>x["replayed"]!.GetValue<bool>());Assert.Equal(replies[0]["order"]!.ToJsonString(),replies[1]["order"]!.ToJsonString());
    }
    [Fact]public async Task TwoCommandsForOneScopeAndOrderVersusRevokeCannotBothConsumeOrRevokeTheSameAuthority()
    {
        using var finance=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var s=await Ready(finance,reviewer);using var customer=s.Customer;var results=await Task.WhenAll(customer.PostAsJsonAsync(Route(Id()),Input(s.Quote)),customer.PostAsJsonAsync(Route(Id()),Input(s.Quote)));Assert.Single(results,r=>r.StatusCode==HttpStatusCode.OK);Assert.Single(results,r=>r.StatusCode==HttpStatusCode.Conflict);foreach(var r in results)r.Dispose();
        var race=await Ready(finance,reviewer);using var racing=race.Customer;var scopeId=V(race.Scope["scope"]!,"id");var app=V(race.Scope["application"]!,"id");var replies=await Task.WhenAll(racing.PostAsJsonAsync(Route(Id()),Input(race.Quote)),racing.PostAsJsonAsync("/api/credit/applications/"+app+"/purchase-scope/revoke/"+Id(),new RevokeCreditPurchaseScopeInput(V(race.Scope["application"]!,"version"),V(race.Scope["scope"]!,"version"),"fa","ابطال ساختگی مسابقه",true)));Assert.Single(replies,r=>r.StatusCode==HttpStatusCode.OK);Assert.Single(replies,r=>r.StatusCode==HttpStatusCode.Conflict);foreach(var r in replies)r.Dispose();
        await using var dbScope=sql.Factory.Services.CreateAsyncScope();var credit=dbScope.ServiceProvider.GetRequiredService<CreditDbContext>();var used=await credit.PurchaseScopeUses.AnyAsync(x=>x.ScopeId==scopeId);var revoked=await credit.ScopeRevocations.AnyAsync(x=>x.ScopeId==scopeId);Assert.True(used^revoked);Assert.Equal(used,await dbScope.ServiceProvider.GetRequiredService<SalesDbContext>().CreditOrderLinks.AnyAsync(x=>x.ScopeId==scopeId));
    }
    [Fact]public async Task TwoOwnersCannotReserveTheSameLastUnitAndOnlyTheWinnerUsesAPurchaseScope()
    {
        using var finance=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var goods=await Product(1);var first=await Ready(finance,reviewer,goods);using var a=first.Customer;var second=await Ready(finance,reviewer,goods);using var b=second.Customer;
        var responses=await Task.WhenAll(a.PostAsJsonAsync(Route(Id()),Input(first.Quote)),b.PostAsJsonAsync(Route(Id()),Input(second.Quote)));Assert.Single(responses,r=>r.StatusCode==HttpStatusCode.OK);Assert.Single(responses,r=>r.StatusCode==HttpStatusCode.Conflict);foreach(var response in responses){if(response.IsSuccessStatusCode)await Read(response);else response.Dispose();}
        await using var scope=sql.Factory.Services.CreateAsyncScope();var sp=scope.ServiceProvider;var stock=await sp.GetRequiredService<InventoryDbContext>().Stock.AsNoTracking().SingleAsync(x=>x.VariantId==goods.Variant);Assert.Equal(1,stock.OnHand);Assert.Equal(1,stock.Reserved);Assert.Equal(0,stock.SourcingReserved);var ids=new[]{V(first.Scope["scope"]!,"id"),V(second.Scope["scope"]!,"id")};Assert.Single(await sp.GetRequiredService<CreditDbContext>().PurchaseScopeUses.Where(x=>ids.Contains(x.ScopeId)).ToArrayAsync());
    }
    private sealed class OrderClock(DateTimeOffset at):TimeProvider{public override DateTimeOffset GetUtcNow()=>at;}
    [Fact]public async Task ExpiryRejectsNewOrdersWithoutEffectsButCannotEraseTheOriginalCommittedReceipt()
    {
        using var finance=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var s=await Ready(finance,reviewer);using var customer=s.Customer;var other=await Ready(finance,reviewer);using var uncommitted=other.Customer;var command=Id();var receipt=await Read(await customer.PostAsJsonAsync(Route(command),Input(s.Quote)));
        using var future=sql.Factory.WithWebHostBuilder(b=>b.ConfigureTestServices(services=>services.AddSingleton<TimeProvider>(new OrderClock(DateTimeOffset.Parse(V(other.Quote,"expiresAt")).AddHours(1)))));using var oldOwner=future.CreateClient(new(){HandleCookies=false});using var newOwner=future.CreateClient(new(){HandleCookies=false});foreach(var h in customer.DefaultRequestHeaders)oldOwner.DefaultRequestHeaders.TryAddWithoutValidation(h.Key,h.Value);foreach(var h in uncommitted.DefaultRequestHeaders)newOwner.DefaultRequestHeaders.TryAddWithoutValidation(h.Key,h.Value);
        var replay=await Read(await oldOwner.PostAsJsonAsync(Route(command),Input(s.Quote)));Assert.True(replay["replayed"]!.GetValue<bool>());Assert.Equal(receipt["order"]!.ToJsonString(),replay["order"]!.ToJsonString());using(var expired=await newOwner.PostAsJsonAsync(Route(Id()),Input(other.Quote)))Assert.Equal(HttpStatusCode.Conflict,expired.StatusCode);var ready=await Read(await newOwner.GetAsync("/api/credit-orders/quotes/"+V(other.Quote,"id")+"/readiness"));Assert.False(ready["canCreate"]!.GetValue<bool>());
        await using var scope=sql.Factory.Services.CreateAsyncScope();Assert.False(await scope.ServiceProvider.GetRequiredService<SalesDbContext>().Orders.AnyAsync(x=>x.OwnerId==other.Owner));Assert.False(await scope.ServiceProvider.GetRequiredService<CreditDbContext>().PurchaseScopeUses.AnyAsync(x=>x.ScopeId==V(other.Scope["scope"]!,"id")));Assert.Equal(0,(await scope.ServiceProvider.GetRequiredService<InventoryDbContext>().Stock.SingleAsync(x=>x.VariantId==other.Goods.Variant)).Reserved);
    }
    [Fact]public async Task StaffFinancialDetailsRequireSalesWriteMfaAndCannotSubstituteOwnerOrAlterCommandConsent()
    {
        using var finance=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");using var salesManager=await Staff("SalesManager");var s=await Ready(finance,reviewer);using var customer=s.Customer;var command=Id();var body=Input(s.Quote);using(var forged=await customer.PostAsJsonAsync(Route(Id()),new{body.CreditQuoteId,body.Fingerprint,body.ContactName,body.ContactPhone,body.Delivery,body.Note,body.QuoteAccepted,body.AcknowledgeTemporary,amountRial="1"}))Assert.Equal(HttpStatusCode.BadRequest,forged.StatusCode);using(var wrong=await customer.PostAsJsonAsync(Route(Id()),body with{Fingerprint=new string('0',64)}))Assert.Equal(HttpStatusCode.Conflict,wrong.StatusCode);
        var created=await Read(await customer.PostAsJsonAsync(Route(command),body));var id=V(created["order"]!["summary"]!,"id");var path="/api/admin/credit-orders/"+s.Owner+"/"+id;var staff=await Read(await salesManager.GetAsync(path));Assert.Equal(id,V(staff["order"]!["summary"]!,"id"));foreach(var denied in new[]{finance,reviewer,customer}){using var r=await denied.GetAsync(path);Assert.Equal(HttpStatusCode.Forbidden,r.StatusCode);}using(var wrongOwner=await salesManager.GetAsync("/api/admin/credit-orders/other_owner/"+id))Assert.Equal(HttpStatusCode.NotFound,wrongOwner.StatusCode);using(var query=await salesManager.GetAsync(path+"?ownerId=other_owner"))Assert.Equal(HttpStatusCode.BadRequest,query.StatusCode);using(var changed=await customer.PostAsJsonAsync(Route(command),body with{ContactName="Different synthetic QA recipient"}))Assert.Equal(HttpStatusCode.Conflict,changed.StatusCode);
    }
    [Fact]public async Task NewLinkAndScopeUseMigrationGuardsAndSqlChecksPreserveCommittedHistory()
    {
        using var finance=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var s=await Ready(finance,reviewer);using var customer=s.Customer;var result=await Read(await customer.PostAsJsonAsync(Route(Id()),Input(s.Quote)));var id=V(result["order"]!["summary"]!,"id");var scopeId=V(s.Scope["scope"]!,"id");
        await using var scope=sql.Factory.Services.CreateAsyncScope();var sp=scope.ServiceProvider;var sales=sp.GetRequiredService<SalesDbContext>();var credit=sp.GetRequiredService<CreditDbContext>();
        var budget=await Assert.ThrowsAsync<SqlException>(()=>sales.Database.ExecuteSqlInterpolatedAsync($"UPDATE [sales].[CreditOrderLinks] SET [AssessedAmountRial]=[LimitAmountRial]+1 WHERE [OrderId]={id}"));Assert.Equal(547,budget.Number);var sameCase=await Assert.ThrowsAsync<SqlException>(()=>credit.Database.ExecuteSqlInterpolatedAsync($"UPDATE [credit].[PurchaseScopeUses] SET [ApplicationId]={Id()} WHERE [ScopeId]={scopeId}"));Assert.Equal(547,sameCase.Number);
        var salesHistory=(await sales.Database.GetAppliedMigrationsAsync()).ToArray();var ownSales=Assert.Single(salesHistory,x=>x.EndsWith("_CreditOrderLinks",StringComparison.Ordinal));
        // Test this published migration at its own schema; later empty features
        // may be rolled down only inside this disposable class fixture.
        try{await sales.GetService<IMigrator>().MigrateAsync(ownSales);var pinned=(await sales.Database.GetAppliedMigrationsAsync()).ToArray();Assert.EndsWith("_CreditOrderLinks",pinned[^1]);var salesDown=await Assert.ThrowsAsync<SqlException>(()=>sales.GetService<IMigrator>().MigrateAsync(pinned[^2]));Assert.Equal(51000,salesDown.Number);Assert.Equal(pinned,await sales.Database.GetAppliedMigrationsAsync());}finally{await sales.Database.MigrateAsync();}Assert.Equal(salesHistory,await sales.Database.GetAppliedMigrationsAsync());
        var creditHistory=(await credit.Database.GetAppliedMigrationsAsync()).ToArray();var own=Assert.Single(creditHistory,x=>x.EndsWith("_PurchaseScopeUses",StringComparison.Ordinal));await credit.GetService<IMigrator>().MigrateAsync(own);var prior=(await credit.Database.GetAppliedMigrationsAsync()).Reverse().Skip(1).First();var creditDown=await Assert.ThrowsAsync<SqlException>(()=>credit.GetService<IMigrator>().MigrateAsync(prior));Assert.Equal(51000,creditDown.Number);await credit.Database.MigrateAsync();Assert.Equal(creditHistory,await credit.Database.GetAppliedMigrationsAsync());Assert.True(await sales.CreditOrderLinks.AnyAsync(x=>x.OrderId==id));Assert.True(await credit.PurchaseScopeUses.AnyAsync(x=>x.ScopeId==scopeId));
    }
    [Fact]public async Task ChequeEnablementIsIndependentDefaultsOffAndLegacySettingsCannotSilentlyChangeIt()
    {
        using var finance=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var s=await Ready(finance,reviewer);using var customer=s.Customer;
        async Task<CheckoutOrderSettings> Set(bool cash,bool? cheque){await using var scope=sql.Factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<SalesDbContext>();await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable);var old=await db.OrderSettings.AsNoTracking().SingleAsync();var value=await scope.ServiceProvider.GetRequiredService<CheckoutOrderSettingsService>().SaveAsync(new(cash,60,2,Convert.ToBase64String(old.Version),cheque),default);await tx.CommitAsync();return value;}
        var disabled=await Set(true,false);Assert.True(disabled.TemporaryOrdersEnabled);Assert.False(disabled.ChequeOrdersEnabled);
        using(var denied=await customer.PostAsJsonAsync(Route(Id()),Input(s.Quote)))Assert.Equal(HttpStatusCode.Conflict,denied.StatusCode);
        var unavailable=await Read(await customer.GetAsync("/api/credit-orders/quotes/"+V(s.Quote,"id")+"/readiness"));Assert.False(unavailable["canCreate"]!.GetValue<bool>());
        var enabled=await Set(false,true);Assert.False(enabled.TemporaryOrdersEnabled);Assert.True(enabled.ChequeOrdersEnabled);
        var legacy=await Set(false,null);Assert.False(legacy.TemporaryOrdersEnabled);Assert.True(legacy.ChequeOrdersEnabled);
        // The settings revision changed, so the earlier calculation remains stale.
        using(var stale=await customer.PostAsJsonAsync(Route(Id()),Input(s.Quote)))Assert.Equal(HttpStatusCode.Conflict,stale.StatusCode);
        var cart=await Read(await customer.GetAsync("/api/cart/en"));var quote=(await Read(await customer.PostAsJsonAsync(CreditCheckoutQuoteQa.Route(Id()),CreditCheckoutQuoteQa.Input(s.Scope,V(cart,"version"),s.Goods.Method,s.Goods.Plan.Id))))["quote"]!;
        var result=await Read(await customer.PostAsJsonAsync(Route(Id()),Input(quote)));Assert.Equal("AwaitingPayment",V(result["order"]!["summary"]!,"state"));Assert.False(result["order"]!["canPay"]!.GetValue<bool>());
    }
    [Fact]public async Task QuoteHistoryAndReadinessAreOwnedReadonlyAndRetainedAfterScopeUse()
    {
        using var finance=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var s=await Ready(finance,reviewer);using var customer=s.Customer;var id=V(s.Quote,"id");var path="/api/credit-orders/quotes/"+id+"/readiness";
        var ready=await Read(await customer.GetAsync(path));Assert.True(ready["canCreate"]!.GetValue<bool>());Assert.False(ready["canPay"]!.GetValue<bool>());Assert.Equal(V(s.Quote,"fingerprint"),V(ready,"fingerprint"));
        await using(var scope=sql.Factory.Services.CreateAsyncScope()){Assert.False(await scope.ServiceProvider.GetRequiredService<SalesDbContext>().Orders.AnyAsync(x=>x.OwnerId==s.Owner));Assert.False(await scope.ServiceProvider.GetRequiredService<CreditDbContext>().PurchaseScopeUses.AnyAsync(x=>x.ScopeId==V(s.Scope["scope"]!,"id")));}
        var history=await Read(await customer.GetAsync("/api/credit-orders/quotes"));Assert.Null(history["nextCursor"]);Assert.Equal(id,V(Assert.Single(history["items"]!.AsArray())!,"id"));Assert.Null(history["items"]![0]!["orderId"]);
        var stranger=await Customer();using var other=stranger.Client;using(var forbidden=await other.GetAsync(path))Assert.Equal(HttpStatusCode.NotFound,forbidden.StatusCode);Assert.Empty((await Read(await other.GetAsync("/api/credit-orders/quotes")))["items"]!.AsArray());
        using(var bad=await customer.GetAsync("/api/credit-orders/quotes?ownerId=forged"))Assert.Equal(HttpStatusCode.BadRequest,bad.StatusCode);using(var bad=await customer.GetAsync(path+"?ownerId=forged"))Assert.Equal(HttpStatusCode.BadRequest,bad.StatusCode);
        var order=await Read(await customer.PostAsJsonAsync(Route(Id()),Input(s.Quote)));var orderId=V(order["order"]!["summary"]!,"id");var after=await Read(await customer.GetAsync(path));Assert.False(after["canCreate"]!.GetValue<bool>());var retained=await Read(await customer.GetAsync("/api/credit-orders/quotes"));Assert.Equal(orderId,V(Assert.Single(retained["items"]!.AsArray())!,"orderId"));var oldQuote=await Read(await customer.GetAsync("/api/cart/en/v2/credit-quotes/"+id));Assert.Equal(s.Quote.ToJsonString(),oldQuote.ToJsonString());
    }

